"""Owner-private read-only review export of the actual existing Studio backend state.
This page is not an independently rebuilt production system or live Streamlit host.
"""
import json,sys,subprocess,shutil
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]))
from redpad_pipeline.drama_quality import Studio
P=Path(__file__).parent;REPO=P.parents[1]
def export(destination):
 destination=Path(destination);destination.mkdir(parents=True,exist_ok=True)
 s=Studio(REPO/'redpad_studio.db',REPO/'redpad_media');pid=json.loads((P/'project_pointer.json').read_text())['project_id'];snapshot=s.snapshot(pid)
 # A failed real-media gate never creates or advertises a new episode link.
 snapshot['new_episode_created']=False;snapshot['cost_usd']=0;snapshot['preview_kind']='Read-only export of actual isolated REDPAD quality project; live editing stays in the existing Streamlit workbench.'
 snapshot['source_commit']=subprocess.check_output(['git','-C',str(REPO),'rev-parse','HEAD'],text=True).strip();snapshot['git_remote_pushed']=False
 with s.tx() as db:
  snapshot['stages']=[dict(r) for r in db.execute('SELECT stage,source_hash,evidence,reviewer,created FROM dq_stages WHERE project=? ORDER BY created',(pid,))]
  snapshot['reviews']=[dict(r) for r in db.execute('SELECT subject,dimension,decision,reviewer,reviewer_type,evidence FROM dq_reviews WHERE project=? ORDER BY id',(pid,))]
 (destination/'project.json').write_text(json.dumps(snapshot,ensure_ascii=False,indent=2));(P/'actual_status.json').write_text(json.dumps(snapshot,ensure_ascii=False,indent=2))
 for name in ['screenplay_v3.md','DRAMA_QUALITY_README.md']:
  source=P/name if name=='screenplay_v3.md' else REPO/name;shutil.copyfile(source,destination/name)
 shutil.copyfile(P/'research_sources/verified_source_notes.json',destination/'research_sources.json')
 (destination/'audio').mkdir(exist_ok=True);audio=[]
 for a in s.assets(pid):
  if a['kind']=='music' and a['current'] and not any(x['target']==a['target'] for x in audio):
   output=destination/'audio'/(a['target']+'.mp3');subprocess.run(['ffmpeg','-y','-v','error','-i',a['path'],'-c:a','libmp3lame','-b:a','128k',str(output)],check=True)
   cue=snapshot['entries']['music/'+a['target']]['payload'];audio.append({'target':a['target'],'file':'quality/audio/'+output.name,'purpose':cue['purpose'],'interval':[cue['start'],cue['end']],'review_status':'Original musical sketch — not editorially accepted'})
 snapshot['music_sketches']=audio
 refs=[a for a in s.assets(pid) if a['kind']=='reference' and a['target']=='rafi' and a['current']]
 if refs:shutil.copyfile(refs[0]['path'],destination/'rafi_reference.jpg')
 (destination/'project.json').write_text(json.dumps(snapshot,ensure_ascii=False,indent=2))
 return snapshot
HTML='''<!doctype html><html lang="bn"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>REDPAD AI Studio — Realistic Drama Quality Upgrade</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#0d151d;color:#e3e9ec}*{box-sizing:border-box}body{margin:0}header{border-bottom:1px solid #2a3846;padding:23px 5vw;display:flex;justify-content:space-between;gap:20px}.brand{font-size:20px;font-weight:800}.brand b{color:#ff6b60}.small{font-size:12px;color:#94aab9}main{max-width:1400px;padding:35px 5vw;margin:auto}.eyebrow{color:#94a8b5;font-size:12px;letter-spacing:.14em}h1{font-size:38px;margin:13px 0}h2{font-size:23px}p{line-height:1.8;color:#b0c0ca}.notice{border-left:3px solid #ce9a52;background:#25231e;padding:18px;line-height:1.8;color:#dac6a8;border-radius:3px}.metrics,.gates{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin:24px 0}.card,.pane{background:#17232e;border:1px solid #2a3b4a;border-radius:12px;padding:20px}.card strong{font-size:27px;display:block}.card small{color:#8ba3b5}.gate{font-size:14px;line-height:1.8}.pass{color:#8cd0a7}.blocked{color:#edbe78}.actions,nav{display:flex;gap:10px;flex-wrap:wrap;margin:25px 0}a,button{color:#d9e7ef}button,.btn{font:inherit;text-decoration:none;background:#23384a;border:1px solid #3a5367;border-radius:7px;padding:11px 15px;cursor:pointer}button.active,.primary{background:#c95349;border-color:#c95349;color:white}.pane[hidden]{display:none}.items{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px}.item{border:1px solid #334658;border-radius:9px;padding:18px;background:#12202c;line-height:1.8}.item h3{margin-top:0}.item p{font-size:14px}.label{color:#e2c49b;font-size:12px}.ref{display:grid;grid-template-columns:1fr 1fr;gap:24px}.ref img{width:100%;border-radius:10px}audio{width:100%;margin-top:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.7 system-ui;color:#bdccd7}input{width:100%;background:#101e2b;color:white;border:1px solid #3c5367;border-radius:6px;padding:12px;margin-bottom:18px}details{border-bottom:1px solid #2b3d4c;padding:12px 0}summary{cursor:pointer}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:12px;text-align:left;border-bottom:1px solid #304452}footer{color:#7d98aa;border-top:1px solid #2a3b4b;margin-top:30px;padding-top:20px;font-size:12px}@media(max-width:700px){main{padding:22px 16px}h1{font-size:28px}.ref{grid-template-columns:1fr}.items{grid-template-columns:1fr}header{padding:20px 16px}}
</style><header><div class="brand"><b>REDPAD</b> AI STUDIO</div><div class="small">ISOLATED · OWNER-PRIVATE · QUALITY REVIEW EXPORT</div></header><main><div class="eyebrow">EXISTING STUDIO / PERMANENT WORKFLOW UPGRADE</div><h1>বাস্তবধর্মী নাটক: Quality Workbench</h1><p>ঘর ১:১৭ — না-বলা কথা · সংশোধিত প্রোডাকশন প্রজেক্ট</p><div class="notice"><strong>নতুন realistic এপিসোড এখনো তৈরি হয়নি।</strong> এটি প্রকৃত backend checkpoint-এর শুধু দেখার প্রিভিউ। গবেষণা ও script revision সংরক্ষিত; বাস্তব ফুটেজ, স্বাভাবিক অভিনয়সমৃদ্ধ কণ্ঠ এবং পর্যাপ্ত free compute যাচাই না হওয়ায় production আটকে আছে। পুরোনো cartoon-কে নতুন ফল হিসেবে দেখানো হচ্ছে না।</div><div class="metrics"><div class="card"><small>DRAMATIC SCENES</small><strong>৭</strong></div><div class="card"><small>DIALOGUE LINES</small><strong>৩৪</strong></div><div class="card"><small>VARIED SHOT COVERAGE</small><strong>৭০ / ৩০০ সেকেন্ড</strong></div><div class="card"><small>NEW PAID API COST</small><strong>$0.00</strong></div></div><div class="gates" id="gates"></div><div class="actions"><a class="btn primary" href="quality/screenplay_v3.md" download>সংশোধিত screenplay</a><a class="btn" href="quality/project.json" download>প্রকৃত project checkpoint</a><a class="btn" href="quality/verification_report.md" download>যাচাই প্রতিবেদন</a><a class="btn" href="REDPAD_feature_checkpoint.bundle" download>Feature-branch Git checkpoint</a></div><nav><button class="active" data-tab="scenes">দৃশ্য ও দ্বন্দ্ব</button><button data-tab="voices">কণ্ঠ ও continuity</button><button data-tab="sound">Music / SFX</button><button data-tab="research">গবেষণা ও উৎস</button><button data-tab="quality">QA / blockers</button></nav><section id="scenes" class="pane"><input id="search" aria-label="Search scenes" placeholder="দৃশ্য বা সংলাপ খুঁজুন…"><div id="sceneitems" class="items"></div></section><section id="voices" class="pane" hidden><div class="notice">নতুন voice audition পাস করেনি। নীচের speaker assignments কেবল প্রার্থী; স্বাভাবিক বাংলাদেশি উচ্চারণ ও অভিনয়ের গ্রহণযোগ্যতা প্রমাণিত নয়।</div><div class="ref"><div><h2>রাফির সংরক্ষিত photographic reference</h2><img src="quality/rafi_reference.jpg" alt="Existing fictional Rafi reference; not newly generated footage"><p>এই ছবিটি reference। এর pan/zoom-কে নতুন নাটকের ফুটেজ বলা হচ্ছে না।</p></div><div id="characters"></div></div><h2>সংলাপের intention ও performance direction</h2><div id="lineitems"></div></section><section id="sound" class="pane" hidden><div class="notice">শোনার জন্য তিনটি original local musical sketch রাখা হয়েছে। এগুলো সম্পূর্ণ এপিসোডের গৃহীত score নয়। বাদ্যযন্ত্রের স্বাভাবিকতা, আবেগের মিল ও mix আলাদাভাবে review করতে হবে।</div><div id="musicitems" class="items"></div><h2>Scene-specific spotting</h2><div id="cueitems"></div><h2>Action-bound SFX</h2><div id="sfxitems"></div></section><section id="research" class="pane" hidden><p>ফ্যাক্ট, কল্পনা ও কারিগরি যাচাই আলাদা রাখা হয়েছে। বাস্তব local haunting বা রাতের আবহাওয়ার দাবি করা হচ্ছে না।</p><div id="researchitems"></div><a href="quality/research_sources.json" download>Download checked source notes</a></section><section id="quality" class="pane" hidden><h2>যা আটকে আছে</h2><div id="blockers"></div><h2>পরীক্ষিত সফটওয়্যার পরিবর্তন</h2><p>Versioned inputs, selective asset invalidation, no cartoon fallback, reviewer evidence, current-byte-bound approval, separate stems এবং final finishing পরীক্ষা করা হয়েছে। Codec test-এর synthetic pattern-কে realistic footage-এর প্রমাণ ধরা হয়নি।</p><pre id="qatext"></pre><h2>Revision history</h2><div id="stages"></div><h2>Implementation scope</h2><pre id="readme"></pre></section><footer>এই preview live Streamlit editor নয়। Existing Studio-এর no-code authoring/review UI স্থানীয় বিচ্ছিন্ন পরিবেশে পরীক্ষা করা হয়েছে। Original Render service অপরিবর্তিত।<br><span id="commit"></span><br><a href="legacy.html">আগের 2D prototype — realistic ফল নয়</a></footer></main><script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const getEntries=(d,c)=>Object.entries(d.entries).filter(([k])=>k.startsWith(c+'/')).map(([key,v])=>({key,...v.payload}));
fetch('quality/project.json').then(r=>r.json()).then(d=>{const labels={development:'Research / screenplay',editorial:'Written-plan review',capability:'Free access / quota / rights',representative_scene:'Realism + dialogue sample',full_render:'Final episode'};document.querySelector('#gates').innerHTML=Object.entries(labels).map(([k,label])=>`<div class="card gate"><small>${label}</small><div class="${d.gates[k].passed?'pass':'blocked'}">${d.gates[k].passed?'PASS · specified scope only':'BLOCKED / UNVERIFIED'}</div></div>`).join('');
const scenes=getEntries(d,'scene').sort((a,b)=>a.start-b.start),lines=getEntries(d,'line').sort((a,b)=>a.start-b.start);const showScenes=(query='')=>{document.querySelector('#sceneitems').innerHTML=scenes.filter(s=>(JSON.stringify(s)+JSON.stringify(lines.filter(l=>l.scene_id===s.key.split('/')[1]))).toLowerCase().includes(query.toLowerCase())).map(s=>`<article class="item"><span class="label">${esc(s.key)} · ${s.start}–${s.end}s</span><h3>${esc(s.setting)}</h3><p><b>উদ্দেশ্য:</b> ${esc(s.objective)}<br><b>বাধা:</b> ${esc(s.obstacle)}<br><b>পরিবর্তন:</b> ${esc(s.turn)}<br><b>ফল:</b> ${esc(s.consequence)}</p><details><summary>অভিনয় ও সংলাপ</summary><p>${esc(s.action)}</p>${lines.filter(l=>l.scene_id===s.key.split('/')[1]).map(l=>`<p><span class="label">${l.start}–${l.end}s · ${esc(l.speaker)}</span><br>${esc(l.text)}</p>`).join('')}</details></article>`).join('');};showScenes();document.querySelector('#search').addEventListener('input',e=>showScenes(e.target.value));
document.querySelector('#characters').innerHTML=getEntries(d,'bible').map(b=>`<details><summary>${esc(b.key)}</summary><p>${esc(b.identity)}</p><p>${esc(b.continuity)}</p><p>${esc(b.voice_speaker)} · ${esc(b.voice_direction)}</p></details>`).join('');document.querySelector('#lineitems').innerHTML=lines.map(l=>`<details><summary>${esc(l.key)} · ${esc(l.speaker)} · ${esc(l.text)}</summary><p>To: ${esc(l.addressee)}<br>Intention: ${esc(l.intention)}<br>Emotion: ${esc(l.emotion)}<br>Pace / pause: ${esc(l.pace)} / ${esc(l.pauses)}</p></details>`).join('');
document.querySelector('#musicitems').innerHTML=(d.music_sketches||[]).map(m=>`<article class="item"><h3>${esc(m.target)} · ${m.interval[0]}–${m.interval[1]}s</h3><p>${esc(m.purpose)}</p><audio controls preload="none" src="${esc(m.file)}"></audio><p class="small">${esc(m.review_status)}</p></article>`).join('');document.querySelector('#cueitems').innerHTML=getEntries(d,'music').map(m=>`<details><summary>${esc(m.key)} · ${m.start}–${m.end}s · ${esc(m.treatment)}</summary><p>${esc(m.purpose)}<br>${esc(m.progression)}<br>${esc(m.instrumentation||'No composed score here')}</p></details>`).join('');document.querySelector('#sfxitems').innerHTML='<table><tr><th>Event</th><th>Timing</th><th>Purpose / perspective</th></tr>'+getEntries(d,'sfx').map(s=>`<tr><td>${esc(s.key)}<br>${esc(s.kind)}</td><td>${s.global_start}s / ${s.duration}s</td><td>${esc(s.event)}<br>${esc(s.distance)} · ${esc(s.perspective)}</td></tr>`).join('')+'</table>';
document.querySelector('#researchitems').innerHTML=getEntries(d,'research').map(r=>`<article class="item"><span class="label">${esc(r.classification)}</span><p>${esc(r.claim)}</p><p>${esc(r.application)}</p>${r.source_url?`<a href="${esc(r.source_url)}" target="_blank" rel="noopener">মূল উৎস</a>`:''}<p>${esc(r.source_summary||'Fictional choice — not a factual claim')}</p></article>`).join('');const issues=[...d.gates.production_start.issues,...d.gates.full_render.issues];document.querySelector('#blockers').innerHTML=[...new Set(issues)].map(x=>`<p>• ${esc(x)}</p>`).join('');document.querySelector('#qatext').textContent=JSON.stringify({gates:d.gates,new_episode_created:d.new_episode_created,source_commit:d.source_commit,pushed:d.git_remote_pushed,external_sample:d.entries['capability/sample']?.payload},null,2);document.querySelector('#stages').innerHTML=(d.stages||[]).map(s=>`<details><summary>${esc(s.stage)} · ${esc(s.reviewer)}</summary><p>${esc(s.evidence)}</p></details>`).join('');document.querySelector('#commit').textContent='Local feature branch commit: '+d.source_commit+' · GitHub push withheld for Render safety.';});
document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('main>section').forEach(p=>p.hidden=p.id!==b.dataset.tab);document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));}));fetch('quality/DRAMA_QUALITY_README.md').then(r=>r.text()).then(t=>document.querySelector('#readme').textContent=t);
</script></html>'''
if __name__=='__main__':
 dest=Path(sys.argv[1]);export(dest/'quality');old=dest/'index.html'
 if old.exists() and not (dest/'legacy.html').exists():shutil.copyfile(old,dest/'legacy.html')
 old.write_text(HTML);print('Exported actual quality status. No new final-video link was created.')
